{/* X labels */}
{labels.map((l, i) => {
  const x =
    padding.left +
    (labels.length === 1
      ? (W - padding.left - padding.right) / 2
      : (i / (labels.length - 1)) * (W - padding.left - padding.right));
  // show every Nth label to avoid clutter
  const step = Math.ceil(labels.length / QDPresentation.chartGeometry.maxLabels);
  if (i % step !== 0 && i !== labels.length - 1) return null;
  // 끝 글자가 그림 밖으로 잘렸다(«27-03-» · 화면 검토 A78 · 2026-09-27). 양 끝은 안쪽으로 붙인다
  const anchor = labels.length > 1 && i === 0 ? 'start' : labels.length > 1 && i === labels.length - 1 ? 'end' : 'middle';
  return (
    <text
      key={i}
      x={x}
      y={H - QDPresentation.chartGeometry.xLabelInset}
      fontSize={QDScale.font[12]}
      fill={T.muted}
      textAnchor={anchor}
      fontFamily={QDScale.family.mono}
    >
      {l}
    </text>
  );
})}
